preConditionHook:
// INNER BOX FALSE BREAK RECLAIM (Brian's notes ON-3, #3, p.2). Inside a live
// swing box (below), an INNER box is formed by the first swingStrength-bar
// pivot after anchor B (p1) and the first pivot of the opposite type after it
// (p2), latched so pivots made during the false break cannot move it (no
// window-extreme requirement, per the note). It must sit strictly inside the
// outer box and be at least minBoxAtr x ATR(boxAtrLength) high. Long: a close
// below the inner box low (still inside the outer box, since a live box has
// not been traded through), after that the FIRST close back above the inner low --
// the most recent close below it lies within the last maxWaitBars bars and on
// or after the bar p2 was confirmed, and no close since after that was above it.
// Short mirrors at the inner box high. maxWaitBars bounds a wait the note
// leaves open.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently. The local counter is
// atrLen, not the input.
if (atrLen != (int)boxAtrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)boxAtrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)boxAtrLength;
} else {
    const int out = (int)boxAtrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)boxAtrLength;
// SWING BOX (ON-1-a) -- one inlined form, copied verbatim into
// ChannelFailedSwingFromHitSide, ChannelInnerSwingBreakFade and
// InnerBoxFalseBreakReclaim. A horizontal box from an anchor pair of confirmed
// swingStrength-bar pivots, in either ordering (Brian 2026-11-05): anchor A is
// a swing low that is also the lowest low of the anchorLookback bars ENDING AT
// it, and B is the very next pivot in time and is a swing high (boxOrder 1,
// "LH": boxLow = low[A], boxHigh = high[B]); or the mirror, A a swing high that
// is the anchorLookback-bar highest high and B the next pivot, a swing low
// (boxOrder 2, "HL"). The box is live while no bar since A has traded below
// boxLow or above boxHigh; a bar AT a side is a hit, not a break. LATCHED:
// while live, a newer qualifying pair does not replace it; on the bar it
// breaks, the scan looks again for the most recent qualifying pair. boxBarA /
// boxBarB are bars-ago and advance one per bar while latched; boxNew marks the
// bar a box latched. The candidate pivots lie in bars swingStrength ..
// maxLookback - 1.
//
// Pivots are NON-ALTERNATING and use the measured SwingHigh test, hand-rolled
// as in SwingPivotTarget because the pair scan needs both types in time order
// (EL_Swing_Probe.txt): AT OR ABOVE the swingStrength OLDER bars, STRICTLY
// ABOVE the swingStrength NEWER bars (the smaller bxK), lag exactly
// swingStrength; the low side mirrors. A bar that is both a swing high and a
// swing low counts as both (Brian 2026-11-05): a green bar (close > open) made
// its low first, any other bar its high first. The scan runs NEWEST-FIRST, so
// the event examined as A sees the event immediately newer than it
// (bxNextT / bxNextBar) as its B. bxRunLo / bxRunHi are the lowest low and
// highest high of bars 0 .. A: the "nothing since A took either side out"
// test. No Break -- not a registered word.
boxNew = false;
if (boxLive) {
    boxBarA = boxBarA + 1;
    boxBarB = boxBarB + 1;
    if (el_lt(low[0], boxLow) || el_gt(high[0], boxHigh)) boxLive = false;
}
if (!boxLive) {
    bxFound = false;
    bxNextT = 0;
    bxNextBar = -1;
    bxRunLo = low[0];
    bxRunHi = high[0];
    for (int j = 0; j <= (int)maxLookback - 1; ++j) {
        if (el_lt(low[j], bxRunLo)) bxRunLo = low[j];
        if (el_gt(high[j], bxRunHi)) bxRunHi = high[j];
        if (j >= (int)swingStrength) {
            bxIsH = true;
            bxIsL = true;
            for (int k = j - (int)swingStrength; k <= j - 1; ++k) {
                if (el_le(high[j], high[k])) bxIsH = false;
                if (el_ge(low[j], low[k])) bxIsL = false;
            }
            for (int k = j + 1; k <= j + (int)swingStrength; ++k) {
                if (el_lt(high[j], high[k])) bxIsH = false;
                if (el_gt(low[j], low[k])) bxIsL = false;
            }
            bxEv1 = 0;
            bxEv2 = 0;
            if (bxIsH) bxEv1 = 1;
            if (bxIsL) bxEv1 = -1;
            if (bxIsH && bxIsL) {
                bxEv1 = -1;
                bxEv2 = 1;
                if (el_gt(close[j], open[j])) {
                    bxEv1 = 1;
                    bxEv2 = -1;
                }
            }
            for (int e = 1; e <= 2; ++e) {
                bxT = bxEv1;
                if (e == 2) bxT = bxEv2;
                if (bxT != 0) {
                    if (!bxFound && bxNextT == -bxT) {
                        bxOk = true;
                        if (bxT == -1) {
                            for (int k = j + 1; k <= j + (int)anchorLookback - 1; ++k) {
                                if (el_gt(low[j], low[k])) bxOk = false;
                            }
                            if (bxOk && el_ge(bxRunLo, low[j]) && el_le(bxRunHi, high[bxNextBar])) {
                                bxFound = true;
                                boxOrder = 1;
                                boxLow = low[j];
                                boxHigh = high[bxNextBar];
                                boxBarA = j;
                                boxBarB = bxNextBar;
                            }
                        }
                        if (bxT == 1) {
                            for (int k = j + 1; k <= j + (int)anchorLookback - 1; ++k) {
                                if (el_lt(high[j], high[k])) bxOk = false;
                            }
                            if (bxOk && el_le(bxRunHi, high[j]) && el_ge(bxRunLo, low[bxNextBar])) {
                                bxFound = true;
                                boxOrder = 2;
                                boxHigh = high[j];
                                boxLow = low[bxNextBar];
                                boxBarA = j;
                                boxBarB = bxNextBar;
                            }
                        }
                    }
                    bxNextT = bxT;
                    bxNextBar = j;
                }
            }
        }
    }
    if (bxFound) {
        boxLive = true;
        boxNew = true;
    }
}
// INNER PAIR. On the bar a box latches, bars boxBarB .. swingStrength are
// REPLAYED oldest-first; on later bars only the pivot newly confirmed at
// bars-ago swingStrength is processed. Events in TIME order (a bar that is
// both: green low-after that-high, otherwise high-after that-low, Brian 2026-11-05);
// inPastB turns on at B's own event. inStage: 0 waiting for p1, 1 waiting for
// the opposite-type p2, 2 inner box latched; p2Bar is p2's bars-ago. The
// height test reads the current ATR every bar.
fireL = false;
fireS = false;
if (boxLive) {
    inBType = 1;
    if (boxOrder == 2) inBType = -1;
    inFrom = (int)swingStrength;
    if (inStage == 2) p2Bar = p2Bar + 1;
    if (boxNew) {
        inStage = 0;
        inPastB = false;
        inFrom = boxBarB;
    }
    for (int inJ = inFrom; inJ >= (int)swingStrength; --inJ) {
        inIsH = true;
        inIsL = true;
        for (int k = inJ - (int)swingStrength; k <= inJ - 1; ++k) {
            if (el_le(high[inJ], high[k])) inIsH = false;
            if (el_ge(low[inJ], low[k])) inIsL = false;
        }
        for (int k = inJ + 1; k <= inJ + (int)swingStrength; ++k) {
            if (el_lt(high[inJ], high[k])) inIsH = false;
            if (el_gt(low[inJ], low[k])) inIsL = false;
        }
        inEv1 = 0;
        inEv2 = 0;
        if (inIsH) inEv1 = 1;
        if (inIsL) inEv1 = -1;
        if (inIsH && inIsL) {
            inEv1 = 1;
            inEv2 = -1;
            if (el_gt(close[inJ], open[inJ])) {
                inEv1 = -1;
                inEv2 = 1;
            }
        }
        for (int e = 1; e <= 2; ++e) {
            inT = inEv1;
            if (e == 2) inT = inEv2;
            if (inT != 0) {
                if (inPastB) {
                    if (inStage == 1 && inT == -p1T) {
                        inStage = 2;
                        p2Bar = inJ;
                        if (inT == -1) innerLo = low[inJ];
                        if (inT == 1) innerHi = high[inJ];
                    }
                    if (inStage == 0) {
                        inStage = 1;
                        p1T = inT;
                        if (inT == -1) innerLo = low[inJ];
                        if (inT == 1) innerHi = high[inJ];
                    }
                }
                if (inJ == boxBarB && inT == inBType) inPastB = true;
            }
        }
    }
    if (inStage == 2) {
        if (el_gt(innerLo, boxLow) && el_lt(innerHi, boxHigh) && el_ge(innerHi - innerLo, minBoxAtr * atrVal)) {
            inWait = p2Bar - (int)swingStrength;
            if ((int)maxWaitBars < inWait) inWait = (int)maxWaitBars;
            kL = -1;
            kS = -1;
            for (int k = 1; k <= inWait; ++k) {
                if (kL == -1 && el_lt(close[k], innerLo)) kL = k;
                if (kS == -1 && el_gt(close[k], innerHi)) kS = k;
            }
            if (kL != -1) {
                okL = el_gt(close[0], innerLo);
                for (int k = 1; k <= kL - 1; ++k) {
                    if (el_gt(close[k], innerLo)) okL = false;
                }
                fireL = okL;
            }
            if (kS != -1) {
                okS = el_lt(close[0], innerHi);
                for (int k = 1; k <= kS - 1; ++k) {
                    if (el_lt(close[k], innerHi)) okS = false;
                }
                fireS = okS;
            }
        }
    }
}
